changeSet.sql:
ALTER TABLE public.review DROP CONSTRAINT ck_review_feedback_producer, ADD CONSTRAINT ck_review_feedback_producer
    CHECK (feedback_producer IS NULL
        OR feedback_producer IN ('LEGACY', 'MENTOR', 'WORK_PLACE', 'TEAM', 'OBSERVATIONS'));
ALTER TABLE public.review_job DROP CONSTRAINT ck_review_job_feedback_producer,
    ADD CONSTRAINT ck_review_job_feedback_producer
    CHECK (feedback_producer IN ('LEGACY', 'MENTOR', 'WORK_PLACE', 'TEAM', 'OBSERVATIONS'));
